/* part:page.style.kit.camera-capture */
/* Kit css: Camera capture with consent    kit version 0.2.1    pairs with kit/camera-capture.js
   A sheet over the page; the camera stage is black in both themes.
   Reads --panel --sunk --ink --ink-2 --ink-3 --rule --accent --accent-ink --f-ui, each with a plain fallback (the sheet sits on <body>); --shadow and --radius optional. */
.kit-cam { position: fixed; inset: 0; z-index: 1000; display: flex; align-items: center; justify-content: center; padding: 16px;
  background: rgba(10, 10, 12, .72); }
.kit-cam-sheet { width: 100%; max-width: 640px; max-height: calc(100vh - 32px); overflow: auto; background: var(--panel, #fff); color: var(--ink, #16181d);
  border: 1px solid var(--rule, #c9ced6); border-radius: var(--radius-lg, 8px); padding: 16px; font: 15px/1.5 var(--f-ui, system-ui, sans-serif); box-shadow: var(--shadow, none); }
.kit-cam-title { margin: 0 0 4px; font-size: 1.1em; }
.kit-cam-hint { margin: 0 0 10px; color: var(--ink-3, #6b7280); font-size: .92em; }
.kit-cam-consent { display: grid; gap: 10px; }
.kit-cam-check { display: flex; gap: 10px; align-items: flex-start; padding: 10px 12px; background: var(--sunk, #f2f3f5); border: 1px solid var(--rule, #c9ced6); border-radius: var(--radius, 4px); }
.kit-cam-check input { margin-top: .3em; width: 18px; height: 18px; flex: none; }
.kit-cam-name { font: inherit; color: inherit; background: var(--panel, #fff); border: 1px solid var(--rule, #c9ced6); border-radius: var(--radius, 4px); padding: 6px 10px; }
.kit-cam-stage { position: relative; background: #000; border-radius: var(--radius, 4px); overflow: hidden; line-height: 0; }
.kit-cam-stage video, .kit-cam-stage canvas { width: 100%; max-height: 62vh; object-fit: contain; }
.kit-cam-guide { position: absolute; border: 2px solid rgba(255, 255, 255, .85); border-radius: 10px; box-shadow: 0 0 0 100vmax rgba(0, 0, 0, .35); pointer-events: none; }
.kit-cam-guide-card { left: 12%; right: 12%; top: 50%; aspect-ratio: 85.6 / 54; transform: translateY(-50%); }
.kit-cam-guide-page { left: 22%; right: 22%; top: 5%; bottom: 5%; border-radius: 3px; }
.kit-cam-row { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; margin-top: 10px; }
.kit-cam-grow { flex: 1; }
.kit-cam-btn { font: inherit; color: var(--ink, #16181d); background: var(--panel, #fff); border: 1px solid var(--rule, #c9ced6); border-radius: var(--radius, 4px); padding: 6px 14px; cursor: pointer; }
.kit-cam-btn:disabled { opacity: .5; cursor: default; }
.kit-cam-btn[hidden] { display: none; }
.kit-cam-primary { background: var(--accent, #2f3b9c); color: var(--accent-ink, #fff); border-color: var(--accent, #2f3b9c); }
.kit-cam-btn:focus-visible, .kit-cam-check input:focus-visible { outline: 2px solid var(--accent, #2f3b9c); outline-offset: 2px; }
/* /part:page.style.kit.camera-capture */

/**
 * Camera capture with consent
 * Kit.cameraCapture.open(opts) opens a sheet that asks for consent first (when you give it consent text), then shows the live camera, takes one photo, lets the person retake it, and resolves to {blob, consent} or null. It prefers the back camera for documents and the front one for a person, switches between them, and falls back to the system camera picker when the browser gives no live camera. The consent record says what was agreed, by whom and when.
 *
 * What it is: the one place a page takes a photo of an ID card, a land title, a room or a person. The camera only opens after the consent box is ticked, the consent words travel
 * with the photo, and the stream is stopped the moment the sheet closes. Live camera needs a secure context (https or localhost); elsewhere it uses the file input's capture.
 * API (small and stable):
 *   Kit.cameraCapture.open({title, hint, facing, consent, who, quality, maxSide, guide}) -> Promise<{blob, consent, width, height} | null>
 *     title     the sheet's heading (default "Take a photo")
 *     hint      one line under it (e.g. "Fill the frame, avoid glare")
 *     facing    'environment' (default, documents) or 'user' (a person)
 *     consent   the words the person agrees to; when given the camera opens only after the box is ticked. Omit it to skip the step
 *     who       true: the consent step also asks for the name of the person consenting (required)
 *     quality   JPEG quality 0..1 (default 0.9); maxSide: scale the long side down to this many pixels (default 2400)
 *     guide     'card' draws an ID-card frame over the preview, 'page' a document frame, none by default
 *     from      the element whose theme tokens the sheet wears (default: the element that had focus); the sheet sits on <body>
 *   consent record: {given: true, text, who, at (ISO), facing}
 *   Kit.cameraCapture.supported() -> boolean    a live camera can be asked for here
 *
 * @id        kit.camera-capture
 * @kind      component
 * @group     Kit
 * @status    new
 * @version   0.2.1
 * @updated   2026-11-21
 * @summary   Take one photo after a recorded consent: live camera with a card or page frame, front and back switch, retake, the file picker as fallback, and a consent record with the photo.
 * @tags      camera, photo, consent, id card, document, capture, getusermedia, privacy, kyc, insurance, inspection
 * @requires  none
 * @files     kit/camera-capture.css, kit/samples/camera-capture.json, kit/previews/camera-capture.js
 * @provides  Kit.cameraCapture.open, Kit.cameraCapture.supported
 * @config    Kit.cameraCapture.open(opts) | title, hint, facing (environment or user), consent (text; the step is skipped without it), who (ask the consenting name), quality, maxSide, guide (card or page), from (element whose theme the sheet wears)
 * @tokens    --panel --sunk --ink --ink-2 --ink-3 --rule --accent --accent-ink --f-ui --shadow? --radius? --radius-lg?
 * @globals   none
 * @db        none
 * @source    Catalog harvest, 2026-11-19 | an agreement review board | ID photos on the signer page and consented photos on the board
 * @preview   {"render": "kit.camera-capture", "samples": ["kit/samples/camera-capture.json"]}
 * @changed   0.2.1: the sheet carries the theme tokens of the element that opened it, and every token has a plain fallback; before, a page that set its tokens on a box rather than :root got a see-through sheet.
 */
(function () {
'use strict';
const Kit = window.Kit = window.Kit || { version: '0.1.0' };

const TOKENS = ['--panel', '--sunk', '--ink', '--ink-2', '--ink-3', '--rule', '--accent', '--accent-ink', '--f-ui', '--shadow', '--radius', '--radius-lg'];
const supported = () => !!(navigator.mediaDevices && navigator.mediaDevices.getUserMedia) && window.isSecureContext !== false;

function el(tag, cls, txt) { const e = document.createElement(tag); if (cls) e.className = cls; if (txt != null) e.textContent = txt; return e; }
function btn(txt, cls) { const b = el('button', 'kit-cam-btn' + (cls ? ' ' + cls : ''), txt); b.type = 'button'; return b; }

function picker(facing) {
  return new Promise(resolve => {
    const inp = document.createElement('input'); inp.type = 'file'; inp.accept = 'image/*';
    inp.setAttribute('capture', facing === 'user' ? 'user' : 'environment');
    inp.addEventListener('change', () => resolve(inp.files[0] || null), { once: true });
    inp.addEventListener('cancel', () => resolve(null), { once: true });
    inp.click();
  });
}

function capture(opts = {}) {
  let facing = opts.facing === 'user' ? 'user' : 'environment';
  const quality = opts.quality || 0.9, maxSide = opts.maxSide || 2400;
  return new Promise(resolve => {
    const prev = document.activeElement;
    const back = el('div', 'kit-cam'); back.setAttribute('role', 'dialog'); back.setAttribute('aria-modal', 'true');
    // the sheet sits on <body>, outside whatever box the theme's tokens are set on: carry them over from where it was opened
    const cs = getComputedStyle(opts.from || (prev && prev.nodeType === 1 ? prev : document.body));
    TOKENS.forEach(t => { const v = cs.getPropertyValue(t).trim(); if (v) back.style.setProperty(t, v); });
    const sheet = el('div', 'kit-cam-sheet');
    const h = el('h3', 'kit-cam-title', opts.title || 'Take a photo'); h.id = 'kit-cam-t' + Math.random().toString(36).slice(2, 7);
    back.setAttribute('aria-labelledby', h.id);
    sheet.append(h);
    if (opts.hint) sheet.append(el('p', 'kit-cam-hint', opts.hint));
    back.append(sheet); document.body.append(back);
    let stream = null, consent = null;
    const stop = () => { if (stream) stream.getTracks().forEach(t => t.stop()); stream = null; };
    const finish = v => { stop(); back.remove(); document.removeEventListener('keydown', esc); if (prev && prev.focus) prev.focus(); resolve(v); };
    const esc = e => { if (e.key === 'Escape') finish(null); };
    document.addEventListener('keydown', esc);

    function consentStep() {
      const box = el('div', 'kit-cam-consent');
      const lab = el('label', 'kit-cam-check'); const cb = el('input'); cb.type = 'checkbox';
      lab.append(cb, el('span', null, opts.consent));
      box.append(lab);
      let name = null;
      if (opts.who) { name = el('input', 'kit-cam-name'); name.placeholder = 'Name of the person consenting'; name.autocomplete = 'name'; box.append(name); }
      const row = el('div', 'kit-cam-row'), go = btn('Continue to the camera', 'kit-cam-primary'), no = btn('Cancel');
      go.disabled = true;
      const ok = () => { go.disabled = !(cb.checked && (!name || name.value.trim())); };
      cb.addEventListener('change', ok); if (name) name.addEventListener('input', ok);
      no.addEventListener('click', () => finish(null));
      go.addEventListener('click', () => {
        consent = { given: true, text: opts.consent, who: name ? name.value.trim() : null, at: new Date().toISOString() };
        box.remove(); cameraStep();
      });
      row.append(go, el('span', 'kit-cam-grow'), no); box.append(row); sheet.append(box); cb.focus();
    }

    function cameraStep() {
      const stage = el('div', 'kit-cam-stage'); const video = el('video'); video.playsInline = true; video.muted = true; video.autoplay = true;
      const still = el('canvas'); still.hidden = true;
      stage.append(video, still);
      if (opts.guide === 'card' || opts.guide === 'page') stage.append(el('div', 'kit-cam-guide kit-cam-guide-' + opts.guide));
      const msg = el('p', 'kit-cam-hint', 'Starting the camera…');
      const row = el('div', 'kit-cam-row');
      const snap = btn('Take photo', 'kit-cam-primary'), flip = btn('Switch camera'), redo = btn('Retake'), use = btn('Use this photo', 'kit-cam-primary'), no = btn('Cancel');
      redo.hidden = use.hidden = true;
      row.append(snap, flip, redo, use, el('span', 'kit-cam-grow'), no); sheet.append(stage, msg, row);
      let blob = null;
      const done = b => finish(b ? { blob: b, consent: consent ? { ...consent, facing } : null, width: still.width, height: still.height } : null);
      async function start() {
        stop();
        try {
          stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: { ideal: facing }, width: { ideal: 1920 }, height: { ideal: 1440 } }, audio: false });
          video.srcObject = stream; msg.textContent = ''; snap.focus();
        } catch (e) {
          msg.textContent = 'No live camera here (' + (e.name || 'refused') + '). Opening the camera picker instead.';
          stop(); const f = await picker(facing); if (!f) return finish(null);
          finish({ blob: f, consent: consent ? { ...consent, facing } : null, width: 0, height: 0 });
        }
      }
      no.addEventListener('click', () => finish(null));
      flip.addEventListener('click', () => { facing = facing === 'user' ? 'environment' : 'user'; start(); });
      snap.addEventListener('click', () => {
        const w = video.videoWidth, hh = video.videoHeight; if (!w) return;
        const k = Math.min(1, maxSide / Math.max(w, hh));
        still.width = Math.round(w * k); still.height = Math.round(hh * k);
        still.getContext('2d').drawImage(video, 0, 0, still.width, still.height);
        still.toBlob(b => { blob = b; video.hidden = true; still.hidden = false; snap.hidden = flip.hidden = true; redo.hidden = use.hidden = false; use.focus(); }, 'image/jpeg', quality);
      });
      redo.addEventListener('click', () => { blob = null; video.hidden = false; still.hidden = true; snap.hidden = flip.hidden = false; redo.hidden = use.hidden = true; });
      use.addEventListener('click', () => done(blob));
      if (supported()) start();
      else { msg.textContent = 'Opening the camera picker…'; picker(facing).then(f => f ? finish({ blob: f, consent: consent ? { ...consent, facing } : null, width: 0, height: 0 }) : finish(null)); }
    }

    if (opts.consent) consentStep(); else cameraStep();
  });
}

Kit.cameraCapture = Object.freeze({ open: capture, supported });
})();

/* part:page.script.preview.kit.camera-capture */
/* The catalog's live preview of kit.camera-capture. It rides with the kit and only the catalog page loads it: `adp.py take` leaves it out. */
(function () {
'use strict';
const { html, useState, useEffect } = window.htmPreact;
const P = window.CatalogPreviews = window.CatalogPreviews || {};
const K = () => window.Kit;
const first = (samples, part) => samples[Object.keys(samples).find(k => k.endsWith('/' + part + '.json'))];
const Json = ({ value, label }) => html`<pre class="pv-json" tabindex="0" aria-label=${label}>${JSON.stringify(value, null, 1)}</pre>`;
const Sim = ({ children }) => html`<p class="pv-sim"><b>Sandbox</b> ${children}</p>`;
const Cases = ({ d, value, set, label = 'Use case' }) => html`<div class="pv-row" role="group" aria-label=${label}><span class="pv-label">${label}</span>
  ${d.cases.map(c => html`<button type="button" key=${c.id} class=${'pv-btn' + (c.id === value ? ' pri' : '')} aria-pressed=${c.id === value} onClick=${() => set(c.id)}>${c.label}</button>`)}</div>`;

P['kit.camera-capture'] = ({ samples }) => {
  const d = first(samples, 'camera-capture');
  const [id, setId] = useState(d.cases[0].id);
  const [res, setRes] = useState(null);
  const [url, setUrl] = useState('');
  useEffect(() => () => { if (url) URL.revokeObjectURL(url); }, [url]);
  useEffect(() => { setRes(null); setUrl(''); }, [id]);
  const c = d.cases.find(x => x.id === id);
  async function go() {
    const r = await K().cameraCapture.open({ title: c.title, hint: c.hint, facing: c.facing, consent: c.consent, who: !!c.who, guide: c.guide });
    setRes(r ? { consent: r.consent, size: r.blob.size, width: r.width, height: r.height } : { cancelled: true });
    setUrl(r ? URL.createObjectURL(r.blob) : '');
  }
  return html`<div class="pv-stack">
    <${Cases} d=${d} value=${id} set=${setId}/>
    <${Sim}>the photo and its consent record stay in this tab. ${K().cameraCapture.supported() ? 'This browser can open a live camera.' : 'No live camera here: the kit opens the camera picker instead.'}<//>
    <div class="pv-two">
      <section><p class="pv-label">${c.consent ? 'The consent words' : 'No consent step'}</p>
        <p style="margin:0">${c.consent || 'Nothing personal is photographed, so the page passes no consent text and the camera opens at once.'}</p>
        <p class="pv-label">facing ${c.facing}${c.guide ? ', ' + c.guide + ' frame' : ''}${c.who ? ', asks who consents' : ''}</p>
        <div><button type="button" class="pv-btn pri" onClick=${go}>${c.title}</button></div></section>
      <section><p class="pv-label">What the page gets back</p>
        ${url ? html`<img style="max-width:100%;max-height:260px;border-radius:8px;border:1px solid var(--rule)" src=${url} alt="The photo taken"/>` : ''}
        ${res ? html`<${Json} value=${res} label="The result"/>` : html`<p class="pv-label">Nothing yet.</p>`}</section>
    </div></div>`;
};
})();
/* /part:page.script.preview.kit.camera-capture */
